window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-848567b8ba34c2e7"]={"versions": [{"id": "FIG-848567b8ba34c2e7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Ereignissen im Kontext der AUTOSAR Adaptive Platform Timing Extensions (AUTOSAR_TPS_AdaptivePlatformTimingExtensions), speziell für die Dienstsuche und Dienstinstanz-Ereignisse (Adaptive Service Discovery).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>TDEventServiceInstanceDiscovery</code>: Spezialisierung von <code>TDEventServiceInstance</code>. Besitzt das Attribut <code>+tdEventServiceInstanceDiscoveryType: TDEventServiceInstanceDiscoveryTypeEnum</code>.</li>\n<li><code>TDEventServiceInstance</code>: Basisklasse unter dem Modulkontext <code>TimingDescriptionEvent</code>, referenziert über die gerichtete Assoziationsrolle <code>+serviceInstanceToPortPrototypeMapping</code> mit Kardinalität <code>0..1</code> die Zielklasse <code>ServiceInstanceToPortPrototypeMapping</code> (Paket <code>ServiceInstanceMapping::</code>, spezialisiert aus <code>UploadablePackageElement</code>). Im Diagramm ist dem Klassennamen zusätzlich der Namensraum <code>TDEventServiceInstance::</code> vorangestellt.</li>\n<li><code>UploadablePackageElement</code>: Paket-Element für ladbare Modellbestandteile, spezialisiert durch <code>ServiceInstanceToPortPrototypeMapping</code>.</li>\n<li><code>TDEventServiceInstanceDiscoveryTypeEnum</code>: Enumeration mit den Werten:</li>\n<li><code>adaptiveServiceOfferStarted</code></li>\n<li><code>adaptiveServiceOfferCompleted</code></li>\n<li><code>adaptiveServiceFindStarted</code></li>\n<li><code>adaptiveServiceFindCompleted</code></li>\n<li><code>adaptiveServiceStopSubscriptionStarted</code></li>\n<li><code>adaptiveServiceStopSubscriptionCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionStarted</code></li>\n<li><code>adaptiveServiceSubscriptionCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionAcknowledgeCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionAcknowledgeStarted</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur zur Modellierung von Ereignispunkten im Lebenszyklus der Service Discovery auf der Adaptive Platform. Ein Ereignis vom Typ <code>TDEventServiceInstanceDiscovery</code> referenziert optional eine Port-Instanz-Zuordnung (<code>ServiceInstanceToPortPrototypeMapping</code>) und charakterisiert diskrete Phasenübergänge im Discovery-Ablauf: das Starten und Abschließen des Anbietens eines Dienstes (<code>Offer</code>), des Suchens nach einem Dienst (<code>Find</code>), des Abbestellens (<code>StopSubscription</code>), des Abonnierens (<code>Subscription</code>) sowie der Abonnement-Bestätigung (<code>SubscriptionAcknowledge</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient der Definition von Mess- und Beobachtungspunkten für Timing-Analysen und Latenzketten bei dynamischen Service-Discovery-Vorgängen in adaptive Anwendungen. Die Assoziation zu <code>ServiceInstanceToPortPrototypeMapping</code> ist optional (<code>0..1</code>), wodurch Ereignisse auch generisch oder vor vollendeter Zuordnung erfasst werden können. Implementierende Werkzeuge müssen die Aufzählungswerte zur Klassifizierung der jeweiligen Discovery-Phasen unterstützen.</p>"}, {"id": "FIG-fe9abae51e55dc78", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Ereignissen im Kontext der AUTOSAR Adaptive Platform Timing Extensions (AUTOSAR_TPS_AdaptivePlatformTimingExtensions), speziell für die Dienstsuche und Dienstinstanz-Ereignisse (Adaptive Service Discovery).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>TDEventServiceInstanceDiscovery</code>: Spezialisierung von <code>TDEventServiceInstance</code>. Besitzt das Attribut <code>+tdEventServiceInstanceDiscoveryType: TDEventServiceInstanceDiscoveryTypeEnum</code>.</li>\n<li><code>TDEventServiceInstance</code>: Basisklasse unter dem Modulkontext <code>TimingDescriptionEvent</code>, referenziert über die gerichtete Assoziationsrolle <code>+serviceInstanceToPortPrototypeMapping</code> mit Kardinalität <code>0..1</code> die Zielklasse <code>ServiceInstanceToPortPrototypeMapping</code> (spezialisiert aus <code>UploadablePackageElement</code>).</li>\n<li><code>UploadablePackageElement</code>: Paket-Element für ladbare Modellbestandteile, spezialisiert durch <code>ServiceInstanceToPortPrototypeMapping</code>.</li>\n<li><code>TDEventServiceInstanceDiscoveryTypeEnum</code>: Enumeration mit den Werten:</li>\n<li><code>adaptiveServiceOfferStarted</code></li>\n<li><code>adaptiveServiceOfferCompleted</code></li>\n<li><code>adaptiveServiceFindStarted</code></li>\n<li><code>adaptiveServiceFindCompleted</code></li>\n<li><code>adaptiveServiceStopSubscriptionStarted</code></li>\n<li><code>adaptiveServiceStopSubscriptionCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionStarted</code></li>\n<li><code>adaptiveServiceSubscriptionCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionAcknowledgeCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionAcknowledgeStarted</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur zur Modellierung von Ereignispunkten im Lebenszyklus der Service Discovery auf der Adaptive Platform. Ein Ereignis vom Typ <code>TDEventServiceInstanceDiscovery</code> referenziert optional eine Port-Instanz-Zuordnung (<code>ServiceInstanceToPortPrototypeMapping</code>) und charakterisiert diskrete Phasenübergänge im Discovery-Ablauf: das Starten und Abschließen des Anbietens eines Dienstes (<code>Offer</code>), des Suchens nach einem Dienst (<code>Find</code>), des Abbestellens (<code>StopSubscription</code>), des Abonnierens (<code>Subscription</code>) sowie der Abonnement-Bestätigung (<code>SubscriptionAcknowledge</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient der Definition von Mess- und Beobachtungspunkten für Timing-Analysen und Latenzketten bei dynamischen Service-Discovery-Vorgängen in adaptive Anwendungen. Die Assoziation zu <code>ServiceInstanceToPortPrototypeMapping</code> ist optional (<code>0..1</code>), wodurch Ereignisse auch generisch oder vor vollendeter Zuordnung erfasst werden können. Implementierende Werkzeuge müssen die Aufzählungswerte zur Klassifizierung der jeweiligen Discovery-Phasen unterstützen.</p>"}, {"id": "FIG-49fa63df7e3ae56b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Ereignissen im Kontext der AUTOSAR Adaptive Platform Timing Extensions (AUTOSAR_TPS_AdaptivePlatformTimingExtensions), speziell für die Dienstsuche und Dienstinstanz-Ereignisse (Adaptive Service Discovery).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>TDEventServiceInstanceDiscovery</code>: Spezialisierung von <code>TDEventServiceInstance</code>. Besitzt das Attribut <code>+tdEventServiceInstanceDiscoveryType: TDEventServiceInstanceDiscoveryTypeEnum</code>.</li>\n<li><code>TDEventServiceInstance</code>: Basisklasse unter dem Modulkontext <code>TimingDescriptionEvent</code>, referenziert über die gerichtete Assoziationsrolle <code>+serviceInstanceToPortPrototypeMapping</code> mit Kardinalität <code>0..1</code> die Zielklasse <code>ServiceInstanceToPortPrototypeMapping</code> (spezialisiert aus <code>UploadablePackageElement</code>).</li>\n<li><code>UploadablePackageElement</code>: Paket-Element für ladbare Modellbestandteile, spezialisiert durch <code>ServiceInstanceToPortPrototypeMapping</code>.</li>\n<li><code>TDEventServiceInstanceDiscoveryTypeEnum</code>: Enumeration mit den Werten:</li>\n<li><code>adaptiveServiceOfferStarted</code></li>\n<li><code>adaptiveServiceOfferCompleted</code></li>\n<li><code>adaptiveServiceFindStarted</code></li>\n<li><code>adaptiveServiceFindCompleted</code></li>\n<li><code>adaptiveServiceStopSubscriptionStarted</code></li>\n<li><code>adaptiveServiceStopSubscriptionCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionStarted</code></li>\n<li><code>adaptiveServiceSubscriptionCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionAcknowledgeCompleted</code></li>\n<li><code>adaptiveServiceSubscriptionAcknowledgeStarted</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur zur Modellierung von Ereignispunkten im Lebenszyklus der Service Discovery auf der Adaptive Platform. Ein Ereignis vom Typ <code>TDEventServiceInstanceDiscovery</code> referenziert optional eine Port-Instanz-Zuordnung (<code>ServiceInstanceToPortPrototypeMapping</code>) und charakterisiert diskrete Phasenübergänge im Discovery-Ablauf: das Starten und Abschließen des Anbietens eines Dienstes (<code>Offer</code>), des Suchens nach einem Dienst (<code>Find</code>), des Abbestellens (<code>StopSubscription</code>), des Abonnierens (<code>Subscription</code>) sowie der Abonnement-Bestätigung (<code>SubscriptionAcknowledge</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient der Definition von Mess- und Beobachtungspunkten für Timing-Analysen und Latenzketten bei dynamischen Service-Discovery-Vorgängen in adaptive Anwendungen. Die Assoziation zu <code>ServiceInstanceToPortPrototypeMapping</code> ist optional (<code>0..1</code>), wodurch Ereignisse auch generisch oder vor vollendeter Zuordnung erfasst werden können. Implementierende Werkzeuge müssen die Aufzählungswerte zur Klassifizierung der jeweiligen Discovery-Phasen unterstützen.</p>"}], "trans": [{"from": "FIG-848567b8ba34c2e7", "to": "FIG-fe9abae51e55dc78", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Im Klassenkopf von <code>TDEventServiceInstance</code> wurde das überlappende / doppelte Paketpräfix <code>TDEventServiceInstance::</code> entfernt und die Überlagerung durch das Assoziationslabel behoben.</li>\n<li>Bei <code>UploadablePackageElement</code> wurde das Paketpräfix <code>ServiceInstanceMapping::</code> vor <code>ServiceInstanceToPortPrototypeMapping</code> entfernt.</li>\n<li>Der vertikale Abstand zwischen den oberen Klassen und der Enumeration <code>TDEventServiceInstanceDiscoveryTypeEnum</code> wurde bereinigt.</li>\n</ul>"}, {"from": "FIG-fe9abae51e55dc78", "to": "FIG-49fa63df7e3ae56b", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
